#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Edge {
    int w;
    short u, v;

    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> x(n + 1), y(n + 1);
    x[0] = 0;
    y[0] = 0;

    for (int i = 1; i <= n; ++i) {
        cin >> x[i] >> y[i];
    }

    // Gerar todas as arestas
    // As coordenadas estão entre -10000 e 10000, logo a distância ao quadrado máxima é:
    // 20000^2 + 20000^2 = 8 * 10^8, que cabe confortavelmente em um int de 32 bits.
    int total_edges = n + (n * (n - 1)) / 2;
    vector<Edge> edges;
    edges.reserve(total_edges);

    for (int i = 0; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            int dx = x[i] - x[j];
            int dy = y[i] - y[j];
            edges.push_back({dx * dx + dy * dy, (short)i, (short)j});
        }
    }

    sort(edges.begin(), edges.end());

    vector<int> dp(n + 1, 0);
    // Para atualizar transições de mesmo peso simultaneamente
    vector<pair<short, int>> updates;
    updates.reserve(2 * n);

    int max_candies = 0;
    int m = edges.size();

    for (int i = 0; i < m; ) {
        int j = i;
        while (j < m && edges[j].w == edges[i].w) {
            ++j;
        }

        updates.clear();

        for (int k = i; k < j; ++k) {
            short u = edges[k].u;
            short v = edges[k].v;

            if (u == 0) {
                // Aresta do palácio para a tenda v
                if (dp[v] + 1 > max_candies) {
                    max_candies = dp[v] + 1;
                }
            } else {
                // Aresta entre a tenda u e a tenda v
                int val_u = dp[v] + 1;
                int val_v = dp[u] + 1;

                updates.push_back({u, val_u});
                updates.push_back({v, val_v});
            }
        }

        for (const auto& up : updates) {
            if (up.second > dp[up.first]) {
                dp[up.first] = up.second;
            }
        }

        i = j;
    }

    cout << max_candies << "\n";

    return 0;
}
